import math
from mathutils import Vector
ns=bpy.app.driver_namespace['coast_ops']
c=ns['group']('Coast_LoadingProps')
box=ns['box'];wood=ns['wood'];trim=ns['trim'];pale=ns['pale']
for x,z,w,h in [(-3.05,1.35,.74,.70),(-3.6,1.9,.60,.55),(-3.05,1.35,.55,.52)]:
    y=.42+h*.5+( .70 if w==.55 else 0)
    box(c,'Freight crate',(x,y,z),(w,h,w),wood,.025)
    for yy in [y-h*.36,y+h*.36]:box(c,'Crate bracing',(x,yy,z),(w+.035,.07,w+.035),pale,.01)
    for xx in [x-w*.36,x+w*.36]:box(c,'Crate vertical batten',(xx,y,z),(.06,h,w+.045),trim,.008)
for x,z in [(-3.1,-2.2),(-3.8,-2.1)]:
    bpy.ops.mesh.primitive_uv_sphere_add(segments=14,ring_count=8,radius=1,location=(x,-z,.86))
    o=bpy.context.object;o.scale=(.28,.28,.43);ns['move'](o,c,'Cargo barrel',wood)
    for y in [.56,1.1]:
        bpy.ops.mesh.primitive_torus_add(major_radius=.22,minor_radius=.025,major_segments=14,minor_segments=5,location=(x,-z,y))
        ns['move'](bpy.context.object,c,'Barrel binding',ns['iron'])
# Rope laid in a believable coil beside a mooring point.
curve=bpy.data.curves.new('Coiled dock rope','CURVE');curve.dimensions='3D';curve.bevel_depth=.022;curve.bevel_resolution=2
spline=curve.splines.new('POLY');spline.points.add(111)
for i,p in enumerate(spline.points):
    t=i/111;ang=t*math.tau*4;r=.09+.29*t
    p.co=(-3.6+math.cos(ang)*r, .75+math.sin(ang)*r, .44,1)
o=bpy.data.objects.new('Rope coil',curve);c.objects.link(o);o.data.materials.append(pale)
# Braced handcart at the side door.
box(c,'Cart tray',(.8,.65,4.55),(1.3,.12,.95),wood)
for z in [4.05,5.05]:
    box(c,'Cart side',(.8,.85,z),(1.38,.4,.09),pale)
for x in [.15,1.45]:box(c,'Cart end',(x,.85,4.55),(.09,.4,1.05),wood)
for z in [4.0,5.1]:
    bpy.ops.mesh.primitive_cylinder_add(vertices=14,radius=.28,depth=.10,location=(.8,-z,.4),rotation=(math.pi*.5,0,0))
    ns['move'](bpy.context.object,c,'Cart wheel',trim)
    ns['beam'](c,'Cart handle',(.2,.65,z),(-.9,1.0,z),.06,pale)
ns['finish'](c)
for o in c.objects:
    if o.type=='MESH' and o.data.uv_layers:
        for uv in o.data.uv_layers.active.data:
            u,v=uv.uv;uv.uv=(.065+(u%1)*.012,.12+(v%1)*.48)
bpy.ops.object.select_all(action='DESELECT')
for collection in [bpy.data.collections['Coast_HarborOffice'],c]:
    for o in collection.objects:o.hide_set(False);o.select_set(True)
bpy.context.view_layer.objects.active=list(c.objects)[0]
out=Path(bpy.data.filepath).parent.parent/'assets/coast/harbor_office.glb'
bpy.ops.export_scene.gltf(filepath=str(out),export_format='GLB',use_selection=True,export_cameras=False,export_lights=False)
bpy.ops.wm.save_as_mainfile(filepath=bpy.data.filepath)
print('LOADING_DETAILS_EXPORTED')
